const STUDIO_OVERRIDES = (pathname, method) => {
  if (method !== 'GET') return undefined
  if (pathname === '/api/product/home') return HOME
  if (pathname === '/api/product/goals') return { items: [GOAL] }
  if (pathname === `/api/product/goals/${GOAL_ID}`) return GOAL_DETAIL
  if (pathname === '/api/product/reflection/review/902') return REFLECTION
  return undefined
}

const SNAPSHOT = {
  fullPage: false,
  timeout: 30_000,
}

async function expectInterviewStudioNav(page) {
  const nav = page.getByRole('navigation', { name: '主导航' })
  await expect(nav).toBeVisible()
  for (const label of ['首页', '求职目标', '练习', '历史', '我的成竹']) {
    await expect(nav.getByRole('button', { name: label })).toBeVisible()
  }
  await expect(nav.getByRole('button', { name: '资料库' })).toHaveCount(0)
}

test.describe('@visual v2 Studio surfaces', () => {
  test.beforeEach(async ({ context }) => {
    await installMocks(context, {
      messages: COMMON_WS_BOOTSTRAP,
      localStorage: { 'ia-color-scheme': 'vscode-light-plus' },
      apiOverrides: STUDIO_OVERRIDES,
    })
  })

  test('Action Home — active Goal', async ({ page }) => {
    await page.goto('/#/home')
    await expect(page.getByText('字节跳动 · AI 产品经理').first()).toBeVisible()
    await expect(page.getByText('把 AI 产品判断讲到可验证')).toBeVisible()
    await expect(page.getByText('PRODUCT_CASE')).toHaveCount(0)
    await expectInterviewStudioNav(page)
    await page.waitForTimeout(250)
    await expect(page).toHaveScreenshot('action-home.png', SNAPSHOT)
  })

  test('Goal list — active work', async ({ page }) => {
    await page.goto('/#/goals')
    await expect(page.getByRole('heading', { name: '求职目标', exact: true })).toBeVisible()
    await expect(page.getByText('字节跳动 · AI 产品经理')).toBeVisible()
    await expect(page.getByText('进行中 · 1')).toBeVisible()
    await expect(page.getByText('PRODUCT_CASE')).toHaveCount(0)
    await expectInterviewStudioNav(page)
    await page.waitForTimeout(250)
    await expect(page).toHaveScreenshot('goals.png', SNAPSHOT)
  })

  test('Goal Room — overview', async ({ page }) => {
    await page.goto(`/#/goals/${GOAL_ID}`)
    await expect(page.getByTestId('goal-room')).toBeVisible()
    const tabs = page.getByRole('tablist', { name: '目标视图' })
    await expect(tabs.getByRole('tab', { name: '概览' })).toBeVisible()
    await expect(tabs.getByRole('tab', { name: '准备' })).toBeVisible()
    await expect(tabs.getByRole('tab', { name: /会话/ })).toBeVisible()
    await expect(tabs.getByRole('tab', { name: '录用' })).toHaveCount(0)
    await page.waitForTimeout(250)
    await expect(page).toHaveScreenshot('goal-room-overview.png', SNAPSHOT)
  })

  test('Reflection — evidence first', async ({ page }) => {
    await page.goto('/#/reflection/review/902')
    await expect(page.getByTestId('reflection-page')).toBeVisible()
    await expect(page.getByText('这场复盘的重点')).toBeVisible()
    await expect(page.getByText('把“为什么这样设计”提前到答案第一句').first()).toBeVisible()
    await page.waitForTimeout(250)
    await expect(page).toHaveScreenshot('reflection.png', SNAPSHOT)
  })

  test('Person resume workspace', async ({ page }) => {
    await page.goto('/#/me/resume')
    await expect(page.getByRole('heading', { name: '我的成竹', exact: true })).toBeVisible()
    await expectInterviewStudioNav(page)
    await expect(page.getByTestId('resume-mount-panel')).toBeVisible({ timeout: 8000 })
    await page.waitForTimeout(250)
    await expect(page).toHaveScreenshot('me-resume.png', SNAPSHOT)
  })
})

test.describe('@visual v2 Live Cockpit', () => {
  test('cue-first live workspace after frozen preflight', async ({ context, page }) => {
    await installMocks(context, {
      messages: [
        ...COMMON_WS_BOOTSTRAP,
        {
          type: 'init',
          delay: 30,
          session_id: 'live-ui-1',
          active_id: 'live-ui-1',
          transcriptions: ['你怎么判断这个 Agent 功能真的值得上线？'],
          qa_pairs: [{
            id: 'qa-live-ui',
            question: '你怎么判断这个 Agent 功能真的值得上线？',
            answer: '先给判断：不是看模型能力，而是看用户任务是否被更稳定地完成。\n\n## 证据\n先看任务完成率与人工回退，再看留存和业务指标。',
            thinkContent: '',
            timestamp: T,
            source: 'manual_text',
            model_name: 'GPT-4.1 Mini',
            fastCue: {
              direction: '先讲用户任务是否被稳定完成',
              cues: [
                { text: '任务完成率：用户是否真正完成目标', source: 'WORLD_KNOWLEDGE' },
                { text: '人工回退率：失败是否可控', source: 'WORLD_KNOWLEDGE' },
                { text: '留存与业务指标：确认不是一次性新鲜感', source: 'WORLD_KNOWLEDGE' },
              ],
              cautions: [],
            },
          }],
          is_recording: true,
          is_paused: false,
          stt_loaded: true,
        },
      ],
      localStorage: {
        'ia-color-scheme': 'vscode-dark-plus',
        'ia_app_mode': 'assist',
        'ia_assist_transcript_collapsed': '1',
      },
      apiOverrides: (pathname, method) => {
        if (method === 'GET' && pathname === '/api/product/goals') return { items: [GOAL] }
        if (method === 'GET' && pathname === `/api/product/goals/${GOAL_ID}`) return GOAL_DETAIL
        if (method === 'POST' && pathname === '/api/product/live/preflight') return PREFLIGHT
        if (method === 'POST' && pathname === '/api/product/live/start') {
          return { session_id: 'live-ui-1', goal_id: GOAL_ID, pack: FROZEN_PACK }
        }
        if (method === 'GET' && pathname === '/api/intelligence/pack') {
          return { session_id: 'live-ui-1', frozen: true, pack: FROZEN_PACK, revisions: [] }
        }
        if (method === 'GET' && pathname === '/api/intelligence/session-claims') return []
        return undefined
      },
    })

    await page.goto(`/#/goals/${GOAL_ID}`)
    await expect(page.getByTestId('goal-room')).toBeVisible()
    await page.getByTestId('goal-go-live').click()
    await expect(page.getByTestId('preflight')).toBeVisible()
    await page.getByTestId('preflight-start').click()

    await expect(page).toHaveURL(/#\/live\/live-ui-1/)
    await expect(page.getByTestId('live-status-line')).toContainText('字节跳动')
    await expect(page.getByTestId('live-pack-bar')).toContainText('本场资料已冻结')
    await expect(page.locator('[data-testid="fast-cue"]:visible')).toContainText('先讲用户任务是否被稳定完成')
    await expect(page.getByText('还没生成策略树')).toBeHidden()
    await expect(page.getByTestId('live-secondary-tools')).toBeHidden()
    await page.waitForTimeout(250)
    await expect(page).toHaveScreenshot('live-cockpit.png', SNAPSHOT)
  })
})

